package lifecycle

import (
 "context"
 "errors"
 "os"
 "path/filepath"
 "sync"
 "time"
 "nice-wiki/libs/platform"
)

type snapshotBarrierRecord struct{Input SnapshotBarrierInput `json:"input"`;Epoch string `json:"epoch"`;InputHash string `json:"inputHash"`;Status SnapshotBarrierStatus `json:"status"`;SealHash string `json:"sealHash,omitempty"`;Drained bool `json:"drained"`}
type SnapshotManager struct{config SnapshotConfig;mu sync.Mutex;record *snapshotBarrierRecord;business int;cleanup int;fileOps int;drainCallbacks int;activityRevision int64;changed chan struct{};enter chan struct{};files chan struct{};leases map[*snapshotAdmission]struct{}}
type snapshotAdmissionKey struct{}
type snapshotAdmission struct{manager *SnapshotManager;epoch string;active bool;cleanup bool;deadline time.Time;purpose string;bound bool;operation platform.OperationContext;job platform.ClaimedJob;cancel context.CancelFunc}
// Cleanup只能由固定drain回调收到，构造字段私有；不是对外的任意写通行证。
type SnapshotCleanup struct{manager *SnapshotManager;record *snapshotBarrierRecord;active bool}

func NewSnapshotManager(config SnapshotConfig)(*SnapshotManager,error){
 if config.Owner==""||config.DataRoot==""||config.OpenedDataEpoch==""||config.Runtime==nil||config.BeginDrain==nil||config.Drain==nil||config.Watermark==nil||config.Capture==nil||config.MigrateStage==nil||config.ValidateStaged==nil||config.ValidateManifest==nil||config.StageBudget==nil||config.ObserveWork==nil||config.SealWork==nil||config.ResumeWork==nil||config.VerifyGlobalSeal==nil{return nil,platform.NewError(platform.CodeDependencyUnavailable,false,"真实快照回调尚未完整装配")};if err:=ValidatePrivatePath(config.DataRoot,"directory",false);err!=nil{return nil,err};manager:=&SnapshotManager{config:config,changed:make(chan struct{}),enter:make(chan struct{},1),files:make(chan struct{},1),leases:make(map[*snapshotAdmission]struct{})}
 path:=filepath.Join(config.DataRoot,"control","snapshot-barrier.json");if _,err:=os.Lstat(path);errors.Is(err,os.ErrNotExist){return manager,nil}else if err!=nil{return nil,snapshotIOError(err)};var record snapshotBarrierRecord;if err:=readSnapshotJSON(path,1<<20,&record);err!=nil{return nil,err};record.Input.Epoch=record.Epoch;raw,_:=platform.CanonicalJSON(struct{Request SnapshotBarrierInput;Epoch string}{record.Input,record.Epoch});if record.InputHash!=platform.HashBytes(raw)||(record.Status.State!="released"&&record.Status.DataEpoch!=record.Epoch)||record.Status.Owner!=config.Owner||record.Status.BarrierID!=record.Input.BarrierID||record.Epoch==""{return nil,integrity("屏障持久绑定损坏")};switch record.Status.State{case "released","draining","failed":case "safe":record.Status.State="failed";default:return nil,integrity("屏障持久状态未知")};record.Drained=false;manager.record=&record
 // 重启不能复用上进程的inflight=0结论；旧safe先持久failed，须原sealHash显式resume-drain再重新证明。
 if record.Status.State!="released"{if err:=manager.persistBarrier();err!=nil{return nil,err}};return manager,nil
}
func (m *SnapshotManager) persistBarrier()error{return writeSnapshotJSON(filepath.Join(m.config.DataRoot,"control","snapshot-barrier.json"),m.config.DataRoot,m.record)}
func (m *SnapshotManager) signalLocked(){m.activityRevision++;close(m.changed);m.changed=make(chan struct{})}
func lockSnapshotControl(ctx context.Context,semaphore chan struct{})(func(),error){select{case semaphore<-struct{}{}:return func(){<-semaphore},nil;case <-ctx.Done():return nil,snapshotIOError(ctx.Err())}}
func (m *SnapshotManager) AdmitBusiness(ctx context.Context)(context.Context,func(),error){
 view,err:=m.config.Runtime(ctx);if err!=nil{return nil,nil,err};if view.DataEpoch!=m.config.OpenedDataEpoch{return nil,nil,platform.NewError(platform.CodeVersionMismatch,false,"活跃私有数据尚未对齐运行代次")};if view.Phase!=platform.PhaseRunning||view.Maintenance{return nil,nil,platform.NewError(platform.CodeLocked,true,"维护中不接受新业务")};m.mu.Lock();defer m.mu.Unlock();if m.record!=nil&&m.record.Status.State!="released"{return nil,nil,platform.NewError(platform.CodeLocked,true,"本域屏障仍未解除")};work,cancel:=context.WithCancel(ctx);lease:=&snapshotAdmission{manager:m,epoch:view.DataEpoch,active:true,purpose:"business",cancel:cancel};m.leases[lease]=struct{}{};if op,ok:=platform.OperationContextFrom(ctx);ok{lease.operation=op;lease.bound=true};m.business++;m.signalLocked();release:=func(){m.mu.Lock();defer m.mu.Unlock();if lease.active{lease.active=false;delete(m.leases,lease);cancel();m.business--;m.signalLocked()}};return platform.WithCleanupIssuer(context.WithValue(work,snapshotAdmissionKey{},lease),lease),release,nil
}

// WriteWindow只认本进程已登记且尚未结束的business或cleanup租约；safe后计数为0，没有可被重放的有效租约。
func (m *SnapshotManager) WriteWindow(ctx context.Context)(time.Time,error){
 lease,ok:=ctx.Value(snapshotAdmissionKey{}).(*snapshotAdmission);if !ok||lease.manager!=m{return time.Time{},platform.NewError(platform.CodeLocked,true,"写入没有既有执行窗口")};view,err:=m.config.Runtime(ctx);if err!=nil{return time.Time{},err};m.mu.Lock();defer m.mu.Unlock();if !lease.active||(lease.purpose=="job_claim"&&!lease.bound)||view.DataEpoch!=lease.epoch||view.DataEpoch!=m.config.OpenedDataEpoch{return time.Time{},platform.NewError(platform.CodeVersionMismatch,false,"写入租约已结束或属于旧代次")};if view.Phase==platform.PhaseRunning&&!view.Maintenance&&(m.record==nil||m.record.Status.State=="released"){return time.Time{},nil};if (view.Phase!=platform.PhaseBackupBarrier&&view.Phase!=platform.PhaseRestoreStaging)||!view.Maintenance||m.record==nil||m.record.Status.State!="draining"||view.BarrierID!=m.record.Input.BarrierID||lease.epoch!=m.record.Epoch{return time.Time{},platform.NewError(platform.CodeLocked,true,"本域安全截点已关闭写入")};deadline:=m.record.Input.Deadline;if !deadline.After(time.Now()){return time.Time{},platform.NewError(platform.CodeLocked,true,"既有执行清理窗口已过期")};if !lease.deadline.IsZero()&&lease.deadline.Before(deadline){deadline=lease.deadline};return deadline,nil
}
func(c *SnapshotCleanup)Context(ctx context.Context)(context.Context,func(),error){
 m:=c.manager;op,ok:=platform.OperationContextFrom(ctx);if !ok||m.config.AuthorizeCleanupOrigin==nil{return nil,nil,platform.NewError(platform.CodeDependencyUnavailable,false,"旧执行清理缺真实原对象授权回调")};if err:=m.config.AuthorizeCleanupOrigin(ctx,op);err!=nil{return nil,nil,err};if err:=m.requireDraining(platform.WithoutCleanupIssuer(ctx),c.record.Input.BarrierID);err!=nil{return nil,nil,err};m.mu.Lock();defer m.mu.Unlock();if !c.active||m.record!=c.record||m.record.Status.State!="draining"||op.DataEpoch!=m.record.Epoch{return nil,nil,platform.NewError(platform.CodeLocked,true,"清理回调私有发行器已失效")};return m.newCleanupLocked(ctx,op)
}
func (m *SnapshotManager) runDrainCallback(ctx context.Context,callback func(context.Context,*SnapshotCleanup)error)error{m.mu.Lock();handle:=&SnapshotCleanup{manager:m,record:m.record,active:true};m.drainCallbacks++;m.signalLocked();m.mu.Unlock();err:=callback(ctx,handle);m.mu.Lock();handle.active=false;m.drainCallbacks--;m.signalLocked();m.mu.Unlock();return err}
// EnterBarrier旧入口安全兼容为prepare；绝不单域drain后自行宣称全域safe。
func(m *SnapshotManager)EnterBarrier(ctx context.Context,input SnapshotBarrierInput)(SnapshotBarrierStatus,error){return m.PrepareBarrier(ctx,input)}
func(m *SnapshotManager)PrepareBarrier(ctx context.Context,input SnapshotBarrierInput)(SnapshotBarrierStatus,error){
 unlock,err:=lockSnapshotControl(ctx,m.enter);if err!=nil{return SnapshotBarrierStatus{},err};defer unlock();view,err:=m.config.Runtime(ctx);if err!=nil{return SnapshotBarrierStatus{},err};expected:=platform.PhaseBackupBarrier;if input.Mode=="restore"{expected=platform.PhaseRestoreStaging}else if input.Mode!="backup"{return SnapshotBarrierStatus{},integrity("屏障模式未知")}
 if input.Epoch!=view.DataEpoch||view.DataEpoch!=m.config.OpenedDataEpoch{return SnapshotBarrierStatus{},platform.NewError(platform.CodeVersionMismatch,false,"屏障代次不符")};if !view.Maintenance||view.Phase!=expected||view.BarrierID!=input.BarrierID||!input.Deadline.After(time.Now()){return SnapshotBarrierStatus{},platform.NewError(platform.CodeLocked,true,"运行权威尚未进入该维护屏障")}
 raw,_:=platform.CanonicalJSON(struct{Request SnapshotBarrierInput;Epoch string}{input,input.Epoch});hash:=platform.HashBytes(raw)
 m.mu.Lock();if m.record!=nil&&m.record.Status.State!="released"{if m.record.InputHash!=hash{m.mu.Unlock();return SnapshotBarrierStatus{},platform.NewError(platform.CodeConflict,false,"屏障原输入不同")};if m.record.Status.State=="safe"{status:=m.record.Status;m.mu.Unlock();return status,nil};if m.record.Status.State=="failed"&&m.record.SealHash!=""{m.mu.Unlock();return SnapshotBarrierStatus{},platform.NewError(platform.CodeLocked,true,"重启封口必须先显式resume-drain")}}else{m.record=&snapshotBarrierRecord{Input:input,Epoch:input.Epoch,InputHash:hash,Status:SnapshotBarrierStatus{BarrierID:input.BarrierID,Owner:m.config.Owner,State:"draining",DataEpoch:input.Epoch}}};m.record.Status.State="draining";m.signalLocked();err=m.persistBarrier();if err==nil{for lease:=range m.leases{lease.cancel()}};m.mu.Unlock();if err!=nil{return SnapshotBarrierStatus{},err}
 work,cancel:=context.WithDeadline(ctx,input.Deadline);defer cancel();if err=m.runDrainCallback(work,m.config.BeginDrain);err!=nil{return SnapshotBarrierStatus{},err};m.mu.Lock();defer m.mu.Unlock();return m.record.Status,nil
}
func(m *SnapshotManager)DrainBarrier(ctx context.Context,barrierID string)(SnapshotBarrierStatus,error){
 unlock,err:=lockSnapshotControl(ctx,m.enter);if err!=nil{return SnapshotBarrierStatus{},err};defer unlock();if err=m.requireDraining(ctx,barrierID);err!=nil{return SnapshotBarrierStatus{},err}
 // 回调负责真实旧执行收尾；不先等待business=0阻断跨域清理，不把排队收费任务跑起来清零。
 if err=m.runDrainCallback(ctx,m.config.Drain);err!=nil{return SnapshotBarrierStatus{},err};m.mu.Lock();defer m.mu.Unlock();m.record.Drained=true;m.signalLocked();if err=m.persistBarrier();err!=nil{return SnapshotBarrierStatus{},err};return m.record.Status,nil
}
func(m *SnapshotManager)requireDraining(ctx context.Context,barrierID string)error{
 view,err:=m.config.Runtime(ctx);if err!=nil{return err};m.mu.Lock();defer m.mu.Unlock();if m.record==nil||m.record.Input.BarrierID!=barrierID||m.record.Status.State!="draining"||!m.record.Input.Deadline.After(time.Now())||view.DataEpoch!=m.record.Epoch||view.DataEpoch!=m.config.OpenedDataEpoch||view.BarrierID!=barrierID||!view.Maintenance||(view.Phase!=platform.PhaseBackupBarrier&&view.Phase!=platform.PhaseRestoreStaging){return platform.NewError(platform.CodeLocked,true,"当前不是该屏障的清理阶段")};return nil
}
func(m *SnapshotManager)ObserveBarrier(ctx context.Context,barrierID string)(SnapshotBarrierObservation,error){
 if err:=m.requireDraining(ctx,barrierID);err!=nil{return SnapshotBarrierObservation{},err};m.mu.Lock();revision:=m.activityRevision;m.mu.Unlock();work,err:=m.config.ObserveWork(ctx);if err!=nil{return SnapshotBarrierObservation{},err};watermark,err:=m.config.Watermark(ctx);if err!=nil{return SnapshotBarrierObservation{},err};if work.OutboxRevision<1||work.WorkRevision<1||work.PendingOutbox<0||work.PendingWork<0||watermark<0{return SnapshotBarrierObservation{},integrity("本域持久工作水位未知")};m.mu.Lock();defer m.mu.Unlock();if revision!=m.activityRevision||!m.record.Drained{return SnapshotBarrierObservation{},platform.NewError(platform.CodeConflict,true,"观察期间在途状态改变或尚未drain")};return SnapshotBarrierObservation{Owner:m.config.Owner,ActivityRevision:revision,Work:work,RevisionWatermark:watermark,Business:int64(m.business),Cleanup:int64(m.cleanup),FileOps:int64(m.fileOps),DrainCallbacks:int64(m.drainCallbacks)},nil
}
// SealBarrier将实际活动CAS封口；真实全域/最终broker证明由已装配协调器回调独立核实。
func(m *SnapshotManager)SealBarrier(ctx context.Context,proof SnapshotSealProof)(SnapshotBarrierStatus,error){
 unlock,err:=lockSnapshotControl(ctx,m.enter);if err!=nil{return SnapshotBarrierStatus{},err};defer unlock();raw,err:=platform.CanonicalJSON(proof);if err!=nil{return SnapshotBarrierStatus{},err};hash:=platform.HashBytes(raw);m.mu.Lock();if m.record!=nil&&m.record.Status.State=="safe"&&m.record.SealHash==hash{status:=m.record.Status;m.mu.Unlock();return status,nil};m.mu.Unlock();if err=m.requireDraining(ctx,proof.BarrierID);err!=nil{return SnapshotBarrierStatus{},err};own,err:=validateSnapshotSealProof(proof,m.config.Owner);if err!=nil{return SnapshotBarrierStatus{},err};if err=m.config.VerifyGlobalSeal(ctx,proof,hash);err!=nil{return SnapshotBarrierStatus{},err};view,err:=m.config.Runtime(ctx);if err!=nil{return SnapshotBarrierStatus{},err};if view.DataEpoch!=proof.DataEpoch||view.BarrierID!=proof.BarrierID||!view.Maintenance||(view.Phase!=platform.PhaseBackupBarrier&&view.Phase!=platform.PhaseRestoreStaging){return SnapshotBarrierStatus{},platform.NewError(platform.CodeLocked,true,"封口前运行权威已改变")}
 m.mu.Lock();defer m.mu.Unlock();if m.record.Epoch!=proof.DataEpoch||!m.record.Drained||m.activityRevision!=own.ActivityRevision||m.business!=0||m.cleanup!=0||m.fileOps!=0||m.drainCallbacks!=0||!m.record.Input.Deadline.After(time.Now()){return SnapshotBarrierStatus{},platform.NewError(platform.CodeConflict,true,"本域在途水位已改变，不能封口")}
 // mutex从此禁止新本进程cleanup；SealWork事务再CAS实际全部持久写水位，任何失败保持draining。
 if err=m.config.SealWork(ctx,own.Work,hash);err!=nil{return SnapshotBarrierStatus{},err};m.record.SealHash=hash;m.record.Status.SealProofHash=hash;m.record.Status.State="safe";m.record.Status.RevisionWatermark=own.RevisionWatermark;if err=m.persistBarrier();err!=nil{return SnapshotBarrierStatus{},err};m.signalLocked();return m.record.Status,nil
}
func(m *SnapshotManager)ResumeDrain(ctx context.Context,barrierID,expectedSealHash string)(SnapshotBarrierStatus,error){
 unlock,err:=lockSnapshotControl(ctx,m.enter);if err!=nil{return SnapshotBarrierStatus{},err};defer unlock();view,err:=m.config.Runtime(ctx);if err!=nil{return SnapshotBarrierStatus{},err};m.mu.Lock();defer m.mu.Unlock();if m.record==nil||m.record.Input.BarrierID!=barrierID||m.record.SealHash!=expectedSealHash||!platform.ValidHash(expectedSealHash)||view.BarrierID!=barrierID||view.DataEpoch!=m.record.Epoch||!view.Maintenance||!m.record.Input.Deadline.After(time.Now())||(view.Phase!=platform.PhaseBackupBarrier&&view.Phase!=platform.PhaseRestoreStaging)||m.fileOps!=0{return SnapshotBarrierStatus{},platform.NewError(platform.CodeConflict,false,"重开清理的原封口绑定不符")};if err=m.config.ResumeWork(ctx,expectedSealHash);err!=nil{return SnapshotBarrierStatus{},err};m.record.Status.State="draining";m.record.Drained=false;m.signalLocked();if err=m.persistBarrier();err!=nil{m.record.Status.State="safe";return SnapshotBarrierStatus{},err};return m.record.Status,nil
}
func validateSnapshotSealProof(proof SnapshotSealProof,owner string)(SnapshotBarrierObservation,error){
 owners:=[]string{"identity","site-config","jobs","content","media","model-gateway","knowledge","qa","memory","localization","analytics","traffic-guard","data-protection","public-site"};seen:=map[string]bool{};var own SnapshotBarrierObservation;before,after:=proof.BrokerBefore,proof.BrokerAfter;if before.Revision<1||before!=after||before.PendingDeliveries!=0||before.ActiveLeases!=0||len(proof.Observations)!=len(owners){return own,integrity("broker稳定截点或全域观察不完整")};for i,observation:=range proof.Observations{if i>0&&proof.Observations[i-1].Owner>=observation.Owner{return own,integrity("观察必须按owner唯一排序")};known:=false;for _,expected:=range owners{if observation.Owner==expected{known=true}};if !known||seen[observation.Owner]||observation.ActivityRevision<1||observation.Work.OutboxRevision<1||observation.Work.WorkRevision<1||observation.RevisionWatermark<0||observation.Business!=0||observation.Cleanup!=0||observation.FileOps!=0||observation.DrainCallbacks!=0||observation.Work.PendingOutbox!=0||observation.Work.PendingWork!=0{return own,integrity("全域真实零在途证明不成立")};seen[observation.Owner]=true;if observation.Owner==owner{own=observation}}
 if owner=="jobs"{base:=proof;base.NonJobsSeals=nil;base.NonJobsProofHash="";raw,_:=platform.CanonicalJSON(base);if platform.HashBytes(raw)!=proof.NonJobsProofHash{return own,integrity("最终jobs证明必须对应原完整全域proof")};if len(proof.NonJobsSeals)!=len(owners)-1||!platform.ValidHash(proof.NonJobsProofHash){return own,integrity("jobs必须最后封口且具全部非jobs回执")};seals:=map[string]bool{};for _,seal:=range proof.NonJobsSeals{if seal.Owner=="jobs"||!seen[seal.Owner]||seals[seal.Owner]||seal.SealProofHash!=proof.NonJobsProofHash{return own,integrity("非jobs封口回执绑定不符")};seals[seal.Owner]=true}}else if len(proof.NonJobsSeals)!=0||proof.NonJobsProofHash!=""{return own,integrity("非jobs不能使用jobs最终封口证明")};return own,nil
}
func (m *SnapshotManager) ReleaseBarrier(ctx context.Context,barrierID string)(SnapshotBarrierStatus,error){
 unlock,err:=lockSnapshotControl(ctx,m.enter);if err!=nil{return SnapshotBarrierStatus{},err};defer unlock();view,err:=m.config.Runtime(ctx);if err!=nil{return SnapshotBarrierStatus{},err};if view.DataEpoch!=m.config.OpenedDataEpoch||view.Phase!=platform.PhaseRunning||view.Maintenance||view.RestoreID!=""{return SnapshotBarrierStatus{},platform.NewError(platform.CodeLocked,true,"全局维护尚未解除")};m.mu.Lock();defer m.mu.Unlock();if m.record==nil||m.record.Input.BarrierID!=barrierID{return SnapshotBarrierStatus{},platform.NewError(platform.CodeNotFound,false,"本域屏障不存在")};if m.business!=0||m.cleanup!=0||m.fileOps!=0{return SnapshotBarrierStatus{},platform.NewError(platform.CodeLocked,true,"屏障仍有在途工作")};if m.record.Status.State=="released"{return m.record.Status,nil};watermark,err:=m.config.Watermark(ctx);if err!=nil{return SnapshotBarrierStatus{},err};if watermark<0{return SnapshotBarrierStatus{},integrity("解除屏障时域水位未知")};if m.record.SealHash!=""{if err=m.config.ResumeWork(ctx,m.record.SealHash);err!=nil{return SnapshotBarrierStatus{},err}};m.record.Status.State="released";m.record.Status.DataEpoch=view.DataEpoch;m.record.Status.RevisionWatermark=watermark;if err=m.persistBarrier();err!=nil{m.record.Status.State="draining";return SnapshotBarrierStatus{},err};m.signalLocked();return m.record.Status,nil
}

// AdmitJobClaim只为领取活跃计数，随机claim root没有业务cleanup授权。
func(m *SnapshotManager)AdmitJobClaim(ctx context.Context)(context.Context,func(),error){work,release,err:=m.AdmitBusiness(ctx);if err!=nil{return nil,nil,err};lease:=work.Value(snapshotAdmissionKey{}).(*snapshotAdmission);m.mu.Lock();lease.purpose="job_claim";lease.bound=false;lease.operation=platform.OperationContext{};m.mu.Unlock();return work,release,nil}
// BindJobExecutionScope仅在公共worker已核对ClaimedJob与factory真实op后绑定一次，不生成新付费权限。
func(m *SnapshotManager)BindJobExecutionScope(ctx context.Context,op platform.OperationContext,job platform.ClaimedJob)(context.Context,error){
 lease,ok:=ctx.Value(snapshotAdmissionKey{}).(*snapshotAdmission);if !ok||lease.manager!=m{return nil,platform.NewError(platform.CodeLocked,false,"任务绑定缺原领取私有scope")};m.mu.Lock();defer m.mu.Unlock()
 if !lease.active||lease.purpose!="job_claim"||lease.bound||lease.epoch!=op.DataEpoch||op.CallerService!=m.config.Owner{return nil,platform.NewError(platform.CodeConflict,false,"任务scope已结束、重复绑定或归属错误")}
 lease.purpose="job_execution";lease.bound=true;lease.operation=op;lease.job=job;m.signalLocked();return platform.WithOperationContext(ctx,op),nil
}
